# Compute count of column 'Wins' grouped by 'Date'
print(f"🔧 Computing count of 'Wins' grouped by 'Date'")

# Check if columns exist and operation is valid
if 'Wins' not in df.columns:
    print(f"❌ Error: Column 'Wins' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif 'Date' not in df.columns:
    print(f"❌ Error: Group by column 'Date' not found")
    print(f"Available columns: {df.columns.tolist()}")
elif "count" not in ['count', 'sum', 'avg', 'min', 'max']:
    print(f"❌ Error: Invalid operation 'count'. Valid operations: ['count', 'sum', 'avg', 'min', 'max']")
else:
    try:
        if "count" == "count":
            result = df.groupby('Date')['Wins'].count()
        elif "count" == "sum":
            result = df.groupby('Date')['Wins'].sum()
        elif "count" == "avg":
            result = df.groupby('Date')['Wins'].mean()
        elif "count" == "min":
            result = df.groupby('Date')['Wins'].min()
        elif "count" == "max":
            result = df.groupby('Date')['Wins'].max()

        print(f"✅ Count of 'Wins' by 'Date':")
        print(result)

        # Convert to dataframe for consistency
        result_df = result.reset_index()
        result_df.columns = ['Date', f'count_result']
        print(f"\n🔍 Result as table:")
        print(result_df)

    except Exception as e:
        print(f"❌ Error computing grouped count: {e}")
        print(f"Column dtypes: {df[['Wins', 'Date']].dtypes}")

